pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len > 1 {
        introsort(arr, 0, len - 1, 2 * (len as f64).log2() as usize);
    }
}

fn introsort<T: Ord + Clone>(arr: &mut [T], lo: usize, hi: usize, depth: usize) {
    if hi - lo < 16 {
        insertion_sort(arr, lo, hi);
    } else if depth == 0 {
        heapsort(arr, lo, hi);
    } else {
        let p = partition(arr, lo, hi);
        if p > lo { introsort(arr, lo, p - 1, depth - 1); }
        if p < hi { introsort(arr, p + 1, hi, depth - 1); }
    }
}

fn insertion_sort<T: Ord>(arr: &mut [T], lo: usize, hi: usize) {
    for i in (lo + 1)..=hi {
        let mut j = i;
        while j > lo && arr[j - 1] > arr[j] { arr.swap(j, j - 1); j -= 1; }
    }
}

fn partition<T: Ord + Clone>(arr: &mut [T], lo: usize, hi: usize) -> usize {
    let mid = lo + (hi - lo) / 2;
    if arr[lo] > arr[mid] { arr.swap(lo, mid); }
    if arr[lo] > arr[hi] { arr.swap(lo, hi); }
    if arr[mid] > arr[hi] { arr.swap(mid, hi); }
    arr.swap(mid, hi);
    let pivot = arr[hi].clone();
    let mut i = lo;
    for j in lo..hi {
        if arr[j] <= pivot { arr.swap(i, j); i += 1; }
    }
    arr.swap(i, hi);
    i
}

fn heapsort<T: Ord>(arr: &mut [T], lo: usize, hi: usize) {
    let n = hi - lo + 1;
    for i in (0..n / 2).rev() { sift_down(arr, lo, i, n); }
    for i in (1..n).rev() {
        arr.swap(lo, lo + i);
        sift_down(arr, lo, 0, i);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], lo: usize, start: usize, n: usize) {
    let mut i = start;
    loop {
        let l = 2 * i + 1;
        if l >= n { break; }
        let r = l + 1;
        let max = if r < n && arr[lo + r] > arr[lo + l] { r } else { l };
        if arr[lo + i] >= arr[lo + max] { break; }
        arr.swap(lo + i, lo + max);
        i = max;
    }
}
